// Packed Int8 country membership: (cIdx + 1) per dot, where 0 = none, 1..14 = country index + 1
const PACKED_COUNTRY_DATA = "";

// Packed UInt8 opportunity/city density: 0..255 per dot
const PACKED_DENSITY_DATA = "";

function unpackCountryData(): { countryIds: Int8Array; densities: Float32Array } {
  if (typeof atob === "undefined") {
    return { countryIds: new Int8Array(0), densities: new Float32Array(0) };
  }
  const cBin = atob(PACKED_COUNTRY_DATA);
  const dBin = atob(PACKED_DENSITY_DATA);
  const len = cBin.length;
  const countryIds = new Int8Array(len);
  const densities = new Float32Array(len);

  for (let i = 0; i < len; i++) {
    const rawVal = cBin.charCodeAt(i);
    countryIds[i] = rawVal === 0 ? -1 : (rawVal - 1);
    densities[i] = dBin.charCodeAt(i) / 255;
  }
  return { countryIds, densities };
}

const unpacked = unpackCountryData();
export const DOT_COUNTRY_IDS: Int8Array = unpacked.countryIds;
export const DOT_OPPORTUNITY_DENSITIES: Float32Array = unpacked.densities;
